INSERT INTO libros (slug, titulo, autor, genero, precio, resumen, descripcion, autor_bio) VALUES
  ('cien-anos-de-soledad', 'Cien años de soledad', 'Gabriel García Márquez', 'novela', 15000, 'Una saga familiar atravesada por el realismo mágico en el pueblo de Macondo.', 'Cien años de soledad narra la historia de la familia Buendía a lo largo de siete generaciones en el pueblo ficticio de Macondo. Considerada la obra cumbre del realismo mágico, mezcla lo cotidiano con lo fantástico para retratar el ciclo de la vida, el amor y la soledad.', 'Gabriel García Márquez (1927-2014) fue un escritor y periodista colombiano, ganador del Premio Nobel de Literatura en 1982. Es uno de los máximos exponentes del realismo mágico latinoamericano.'),
  ('rayuela', 'Rayuela', 'Julio Cortázar', 'novela', 14200, 'Una novela experimental que puede leerse en múltiples órdenes.', 'Rayuela sigue a Horacio Oliveira entre París y Buenos Aires. Su estructura en capítulos que pueden leerse en distintos órdenes la convirtió en una de las novelas más innovadoras de la literatura en español.', 'Julio Cortázar (1914-1984) fue un escritor argentino, referente del cuento fantástico y del boom latinoamericano.'),
  ('ficciones', 'Ficciones', 'Jorge Luis Borges', 'cuento', 12800, 'Una colección de cuentos que exploran laberintos, espejos e infinitos.', 'Ficciones reúne algunos de los cuentos más célebres de Borges, como "Tlön, Uqbar, Orbis Tertius" y "La biblioteca de Babel", donde lo filosófico y lo fantástico se cruzan.', 'Jorge Luis Borges (1899-1986) fue un escritor argentino, autor de cuentos, ensayos y poemas, y uno de los escritores más influyentes del siglo XX.'),
  ('la-casa-de-los-espiritus', 'La casa de los espíritus', 'Isabel Allende', 'novela', 13500, 'La historia de la familia Trueba a lo largo de varias generaciones.', 'La casa de los espíritus recorre cuatro generaciones de la familia Trueba, con el trasfondo de los cambios políticos y sociales de un país latinoamericano.', 'Isabel Allende (1942) es una escritora chilena, una de las autoras en español más leídas del mundo.'),
  ('el-tunel', 'El túnel', 'Ernesto Sabato', 'novela', 9900, 'La confesión de un pintor obsesionado tras cometer un crimen pasional.', 'En El túnel, el pintor Juan Pablo Castel cuenta desde la cárcel cómo llegó a matar a María Iribarne, en una novela breve sobre la soledad y la obsesión.', 'Ernesto Sabato (1911-2011) fue un escritor, físico y pintor argentino, autor de El túnel, Sobre héroes y tumbas y Abaddón el exterminador.'),
  ('aura', 'Aura', 'Carlos Fuentes', 'novela', 8700, 'Una nouvelle fantástica narrada en segunda persona.', 'Aura cuenta la historia de Felipe Montero, un joven historiador que acepta un trabajo en una vieja casa del centro de la Ciudad de México, donde nada es lo que parece.', 'Carlos Fuentes (1928-2012) fue un escritor mexicano, figura central del boom latinoamericano.'),
  ('el-aleph', 'El Aleph', 'Jorge Luis Borges', 'cuento', 13100, 'Relatos sobre el infinito, la identidad y los límites de la memoria.', 'El Aleph reúne cuentos en los que una mirada, un objeto o un encuentro abren preguntas sobre el universo y el paso del tiempo.', 'Jorge Luis Borges (1899-1986) fue un escritor argentino, autor de cuentos, ensayos y poemas, y uno de los escritores más influyentes del siglo XX.'),
  ('bestiario', 'Bestiario', 'Julio Cortázar', 'cuento', 11200, 'Lo fantástico irrumpe en casas, viajes y rutinas cotidianas.', 'Bestiario reúne relatos como Casa tomada y Lejana, donde situaciones familiares se transforman lentamente en experiencias inquietantes.', 'Julio Cortázar (1914-1984) fue un escritor argentino, referente del cuento fantástico y del boom latinoamericano.'),
  ('el-llano-en-llamas', 'El llano en llamas', 'Juan Rulfo', 'cuento', 10400, 'Voces del campo mexicano cuentan historias de pérdida y resistencia.', 'El llano en llamas presenta relatos atravesados por la pobreza, los conflictos y la vida rural, con una prosa breve y voces inolvidables.', 'Juan Rulfo (1917-1986) fue un escritor y fotógrafo mexicano, autor de El llano en llamas y Pedro Páramo.'),
  ('pedro-paramo', 'Pedro Páramo', 'Juan Rulfo', 'novela', 11800, 'La búsqueda de un padre lleva a un pueblo habitado por recuerdos.', 'Juan Preciado llega a Comala buscando a su padre, Pedro Páramo, y descubre una historia fragmentada entre voces del presente y del pasado.', 'Juan Rulfo (1917-1986) fue un escritor y fotógrafo mexicano, autor de El llano en llamas y Pedro Páramo.'),
  ('la-invencion-de-morel', 'La invención de Morel', 'Adolfo Bioy Casares', 'novela', 12300, 'Un fugitivo descubre una presencia inexplicable en una isla.', 'En una isla aparentemente desierta, un fugitivo observa a un grupo de visitantes y comienza a investigar una invención que altera su idea de la realidad.', 'Adolfo Bioy Casares (1914-1999) fue un escritor argentino, reconocido por sus novelas y cuentos fantásticos.'),
  ('veinte-poemas-de-amor', 'Veinte poemas de amor y una canción desesperada', 'Pablo Neruda', 'poesia', 8200, 'Poemas sobre el amor, la naturaleza y la ausencia.', 'Este poemario recorre el encuentro amoroso y la nostalgia mediante imágenes del paisaje, el cuerpo y la memoria.', 'Pablo Neruda (1904-1973) fue un poeta chileno, autor de Residencia en la tierra y Canto general.'),
  ('desolacion', 'Desolación', 'Gabriela Mistral', 'poesia', 9100, 'Una voz poética que explora el dolor, la ternura y la enseñanza.', 'Desolación reúne poemas sobre la pérdida, la infancia y la naturaleza, con una voz intensa y cercana a la experiencia cotidiana.', 'Gabriela Mistral (1889-1957) fue una poeta y educadora chilena, figura central de la literatura latinoamericana.'),
  ('languidez', 'Languidez', 'Alfonsina Storni', 'poesia', 7600, 'Poemas que interrogan el deseo, la soledad y las convenciones sociales.', 'Languidez propone una mirada íntima y crítica sobre las relaciones y el lugar de la mujer, con imágenes que oscilan entre la melancolía y la rebeldía.', 'Alfonsina Storni (1892-1938) fue una poeta y escritora argentina, autora de una obra marcada por la autonomía y la sensibilidad social.'),
  ('los-heraldos-negros', 'Los heraldos negros', 'César Vallejo', 'poesia', 8800, 'Versos sobre el sufrimiento humano, la familia y la memoria.', 'Los heraldos negros explora experiencias de dolor y arraigo mediante un lenguaje que anuncia la originalidad de la poesía de Vallejo.', 'César Vallejo (1892-1938) fue un poeta peruano, autor de Trilce y una de las voces fundamentales de la poesía en español.'),
  ('el-rayo-que-no-cesa', 'El rayo que no cesa', 'Miguel Hernández', 'poesia', 9400, 'El amor y la pérdida se expresan en sonetos de gran intensidad.', 'El rayo que no cesa reúne poemas que enlazan deseo, dolor y naturaleza, e incluye la elegía dedicada a Ramón Sijé.', 'Miguel Hernández (1910-1942) fue un poeta y dramaturgo español, reconocido por su poesía amorosa y social.'),
  ('cuentos-de-la-selva', 'Cuentos de la selva', 'Horacio Quiroga', 'infantil', 7900, 'Animales de la selva protagonizan aventuras de amistad y supervivencia.', 'Cuentos de la selva acerca a los lectores jóvenes a un mundo de animales y paisajes de Misiones, con historias de cooperación, peligro y aprendizaje.', 'Horacio Quiroga (1878-1937) fue un escritor uruguayo cuya obra está estrechamente vinculada a la selva misionera.'),
  ('el-principito', 'El principito', 'Antoine de Saint-Exupéry', 'infantil', 8500, 'Un pequeño viajero comparte sus preguntas sobre la amistad y la vida.', 'Un aviador encuentra en el desierto a un niño llegado de otro planeta. Sus conversaciones invitan a mirar los vínculos y las cosas cotidianas de otra manera.', 'Antoine de Saint-Exupéry (1900-1944) fue un escritor y aviador francés, autor de relatos inspirados en sus experiencias de vuelo.'),
  ('dailan-kifki', 'Dailan Kifki', 'María Elena Walsh', 'infantil', 10700, 'La llegada de un elefante transforma una casa en una aventura disparatada.', 'Cuando Dailan Kifki aparece en la puerta de una casa, sus nuevos amigos deben resolver una sucesión de problemas tan inesperados como divertidos.', 'María Elena Walsh (1930-2011) fue una escritora, poeta y compositora argentina, creadora de canciones y libros para distintas generaciones.'),
  ('cuentopos-de-gulubu', 'Cuentopos de Gulubú', 'María Elena Walsh', 'infantil', 9600, 'Cuentos llenos de humor, juegos de palabras y personajes inesperados.', 'Cuentopos de Gulubú reúne historias breves donde la imaginación y el lenguaje crean situaciones absurdas para disfrutar leyendo en voz alta.', 'María Elena Walsh (1930-2011) fue una escritora, poeta y compositora argentina, creadora de canciones y libros para distintas generaciones.')
